  { id: 2, titulo: "Practicar HTTP", completada: true }
];

const server = createServer((req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  if (req.method === "GET" && url.pathname === "/api/tareas") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(tareas));
    return;
  }
  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Ruta no encontrada" }));
});

server.listen(3000);

const url = new URL(req.url ?? "/", "http://localhost");
const coincidencia = url.pathname.match(/^\/api\/tareas\/(\d+)$/);

if (req.method === "GET" && coincidencia) {
  const id = Number(coincidencia[1]);
  const tarea = tareas.find(item => item.id === id);

  if (!tarea) {
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Tarea no encontrada" }));
    return;
  }

  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify(tarea));
}

if (req.method === "POST" && url.pathname === "/api/tareas") {
  try {
    const fragmentos = [];
    for await (const fragmento of req) fragmentos.push(fragmento);
    const entrada = JSON.parse(Buffer.concat(fragmentos).toString("utf8"));

    if (typeof entrada.titulo !== "string" || !entrada.titulo.trim()) {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "El título es obligatorio" }));
      return;
    }

    const nueva = { id: Date.now(), titulo: entrada.titulo.trim(), completada: false };
    tareas.push(nueva);
    res.writeHead(201, { "Content-Type": "application/json" });
    res.end(JSON.stringify(nueva));
  } catch {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "JSON inválido" }));
  }
}

if (url.pathname === "/api/tareas" && req.method !== "GET" && req.method !== "POST") {
  res.writeHead(405, {
    "Content-Type": "application/json",
    "Allow": "GET, POST"
  });
  res.end(JSON.stringify({ error: "Método no permitido" }));
  return;
}

